document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelector(".lightbox");if(!e)return;const t=e.querySelector("img");document.querySelectorAll(".gallery-item").forEach(n=>n.addEventListener("click",s=>{s.preventDefault(),t.src=n.href,e.showModal()})),e.querySelector(".lightbox-close").addEventListener("click",()=>e.close()),e.addEventListener("click",t=>{t.target===e&&e.close()})})